mapper.select:
SELECT s.id, s.sample_no AS sampleNo, s.sample_name AS sampleName, s.inspection_order_id AS inspectionOrderId, io.order_no AS orderNo, s.inspect_item_id AS inspectItemId, ii.code AS inspectItemCode, ii.name AS inspectItemName, m.name AS materialName, m.code AS materialCode, m.specification AS materialSpec, io.batch_no AS batchNo, s.quantity, s.unit_id AS unitId, io.create_time AS requestTime, io.create_by AS requestUserId, s.receive_time AS receiveTime, s.receiver_name AS receiverName, s.create_time AS createTime, s.tag_printed AS tagPrinted FROM lm_sample s LEFT JOIN lm_inspection_order io ON s.inspection_order_id = io.id LEFT JOIN lm_inspect_material m ON io.material_id = m.id LEFT JOIN lm_inspect_item ii ON s.inspect_item_id = ii.id WHERE s.is_deleted = 0 AND s.received = 1 AND s.collected = 0 AND s.discarded = 0 AND s.inspect_item_id IS NOT NULL
AND s.inspect_item_id = #{inspectItemId}
AND ii.name LIKE CONCAT('%', #{inspectItemName}, '%')
AND s.sample_no LIKE CONCAT('%', #{sampleNo}, '%')
AND io.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND m.name LIKE CONCAT('%', #{materialName}, '%')
AND io.batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND io.create_time >= #{inspectionRequestTimeStart}
AND io.create_time <= #{inspectionRequestTimeEnd}
AND m.id IN
#{item}
ORDER BY ii.code ASC, io.create_time ASC

SELECT COALESCE(SUM(CASE WHEN s.processed = 0 AND s.recycled = 0 THEN 1 ELSE 0 END), 0) AS toRecycleCount, COALESCE(SUM(CASE WHEN s.processed = 0 AND s.recycled = 1 THEN 1 ELSE 0 END), 0) AS toProcessCount, COALESCE(SUM(CASE WHEN s.processed = 1 THEN 1 ELSE 0 END), 0) AS processedCount FROM lm_sample s LEFT JOIN lm_inspection_order io ON s.inspection_order_id = io.id LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE s.is_deleted = 0 AND s.received = 1 AND ( io.order_status = 'TERMINATED' OR io.finished = 1 OR io.order_status = 'COMPLETED' )
AND io.material_id IN
#{item}
AND io.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{batchNo}, '%')
AND s.sample_no LIKE CONCAT('%', #{sampleNo}, '%')
AND COALESCE(io.finished_time, io.terminate_time) >= #{endTimeStart}
AND COALESCE(io.finished_time, io.terminate_time) <= #{endTimeEnd}
